export const html = "<header class=\"chrome\">\n  <button class=\"icon-btn glass\" aria-label=\"Close case study\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n  <div class=\"right\">\n    <button class=\"icon-btn glass\" id=\"themeBtn\" aria-label=\"Switch theme\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"8\" cy=\"8\" r=\"5.5\"/><path d=\"M8 2.5v11A5.5 5.5 0 0 0 8 2.5z\" fill=\"currentColor\"/></svg></button>\n    <a class=\"pill-btn glass\" href=\"#next\"><span class=\"muted\">Next</span><span class=\"dot\"></span>LePal</a>\n  </div>\n</header>\n\n<main class=\"wrap\">\n  <section class=\"hero-bleed\" id=\"cover\">\n    <img src=\"/TAPimgs/TAP_case_hero_pic.png\" alt=\"TAP trainee app on laptop and Vision Pro, with the TAP mascot\">\n    <!-- Live thumbnail motion (same as the landing card). Loaded only on the real site; the image above is the poster/fallback. -->\n    <div class=\"hero-media\" id=\"heroMedia\" data-src=\"/thumbs/tap3d.html?theme=dark\" aria-hidden=\"true\"></div>\n    <div class=\"hero-inner\">\n      <div class=\"hero-top\"><span class=\"tag on-img\">TAP3D</span><span class=\"t-small\">VR training for manufacturing technicians</span></div>\n          <div class=\"hero-grid\">\n            <h1 class=\"t-display\">From passive lists<br>to proactive agents</h1>\n        <div class=\"hero-right\">\n          <p class=\"t-lead\"><b>I turned TAP3D's passive checklist into an agent that reaches out first.</b> I proved it with a Wizard-of-Oz study of 24 trainees, and the results got the CFO to greenlight it.</p>\n          <div class=\"tags\"><span class=\"tag on-img\">AI Agent</span><span class=\"tag on-img\">XR</span><span class=\"tag on-img\">Contract</span></div>\n          <button class=\"btn-summary\" data-open-summary><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"2\" y=\"2\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"9\" y=\"2\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"2\" y=\"9\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"9\" y=\"9\" width=\"5\" height=\"5\" rx=\"1\"/></svg>Read the 2-min summary <span class=\"sub\">5 slides</span></button>\n        </div>\n      </div>\n    </div>\n  </section>\n  <section class=\"hero\">\n    <div class=\"meta\">\n      <div><div class=\"t-caption\">Role</div><div class=\"t-label\">Lead Product Designer</div></div>\n      <div><div class=\"t-caption\">Timeline</div><div class=\"t-label\">6 months</div></div>\n      <div><div class=\"t-caption\">Team</div><div class=\"t-label\">PM · Eng · QA</div></div>\n      <div><div class=\"t-caption\">Platform</div><div class=\"t-label\">XR · Web · Tablet</div></div>\n    </div>\n\n    <div class=\"glance-head\"><span class=\"t-caption\">At a glance</span></div>\n    <div class=\"tldr\">\n      <div><div class=\"t-caption\">Problem</div><p class=\"t-small\"><b>Trainees stalled before review.</b> Completion dropped sharply at Module 3, and the data couldn't say why.</p></div>\n      <div><div class=\"t-caption\">What I did</div><p class=\"t-small\"><b>9 interviews, 3 barriers.</b> Designed a proactive AI agent and simulated it with Wizard-of-Oz before any model existed.</p></div>\n      <div><div class=\"t-caption\">Outcome</div><p class=\"t-small\"><b>The CFO said yes.</b> Issue resolution 33% → 71% in simulation; the agent shipped and is being localized for China.</p></div>\n    </div>\n  </section>\n\n  <div class=\"case\">\n    <aside class=\"toc\" id=\"toc\" aria-label=\"Sections\">\n      <ol>\n        <li><a href=\"#context\"><span>01</span>Context</a></li>\n        <li><a href=\"#research\"><span>02</span>Research</a></li>\n        <li><a href=\"#strategy\"><span>03</span>Strategy</a></li>\n        <li><a href=\"#design\"><span>04</span>Design</a></li>\n        <li><a href=\"#validation\"><span>05</span>Validation</a></li>\n        <li><a href=\"#outcome\"><span>06</span>Outcome</a></li>\n        <li><a href=\"#reflection\"><span>07</span>Reflection</a></li>\n      </ol>\n    </aside>\n\n    <div>\n      <!-- 01 -->\n      <section class=\"sec\" id=\"context\">\n        <div class=\"eyebrow\"><span class=\"n\">01</span>Context</div>\n        <h2 class=\"t-h2\">Users were dropping off, but why?</h2>\n        <p class=\"t-body\">TAP3D is a <b>B2B VR training platform</b> preparing workers for advanced manufacturing roles, with one experience across VR and web. Despite that, internal data showed a <b>significant lag in the training completion cycle</b>. Trainees weren't reaching the review stage, and that hit customer retention directly.</p>\n        <div class=\"expect reveal\">\n          <div class=\"chip\"><span class=\"t-caption\">Expected</span><span class=\"t-label\">Complete training</span></div><span class=\"sep\">→</span>\n          <div class=\"chip\"><span class=\"t-caption\">Goal</span><span class=\"t-label\">Higher retention</span></div><span class=\"sep\">≠</span>\n          <div class=\"chip bad\"><span class=\"t-caption\">Reality</span><span class=\"t-label\">Early drop-off</span></div>\n        </div>\n\n        <figure class=\"breakout panel chart reveal\">\n          <div class=\"chart-head\">\n            <div><div class=\"t-label\">Training completion rate</div><div class=\"t-caption\">Monthly cohort · illustrative</div></div>\n            <div class=\"chart-call\"><span class=\"t-label\" style=\"color:var(--accent)\">Module 3</span><span class=\"t-caption\">the steepest drop</span></div>\n          </div>\n          <div class=\"bars\">\n            <div class=\"col\"><span class=\"v\">92%</span><i style=\"--h:92%\"></i><span class=\"l\">Module 1</span></div>\n            <div class=\"col\"><span class=\"v\">74%</span><i style=\"--h:74%\"></i><span class=\"l\">Module 2</span></div>\n            <div class=\"col hot\"><span class=\"v\">41%</span><i style=\"--h:41%\"></i><span class=\"l\">Module 3</span></div>\n            <div class=\"col\"><span class=\"v\">28%</span><i style=\"--h:28%\"></i><span class=\"l\">Module 4</span></div>\n            <div class=\"col\"><span class=\"v\">19%</span><i style=\"--h:19%\"></i><span class=\"l\">Module 5</span></div>\n            <div class=\"col\"><span class=\"v\">12%</span><i style=\"--h:12%\"></i><span class=\"l\">Review</span></div>\n          </div>\n          <figcaption class=\"t-caption\">Values are illustrative. Actual data is confidential.</figcaption>\n        </figure>\n\n        <div class=\"insight reveal\"><p>The logs showed where trainees stopped. <em>They couldn't show why.</em></p></div>\n      </section>\n\n      <!-- 02 -->\n      <section class=\"sec\" id=\"research\">\n        <div class=\"eyebrow\"><span class=\"n\">02</span>Research</div>\n        <h2 class=\"t-h2\">9 interviews. 3 barriers.</h2>\n        <p class=\"t-body\">I ran in-depth interviews with learners and coded every quote into an affinity map to find what the usage data couldn't explain.</p>\n\n        <div class=\"stats-xl reveal\">\n          <div><span class=\"num\">9</span><span class=\"t-small\">in-depth interviews</span></div>\n          <div><span class=\"num\">200+</span><span class=\"t-small\">coded quotes</span></div>\n          <div><span class=\"num accent\">3</span><span class=\"t-small\">cognitive barriers confirmed</span></div>\n        </div>\n\n        <figure class=\"breakout panel shot reveal\" aria-label=\"Affinity map of interview quotes\">\n          <img src=\"/TAPimgs/Tap3D_affinity_mapping.png\" alt=\"Affinity map clustering 200+ interview quotes into three barrier themes: where do I start, why does it matter today, and I'm stuck\" loading=\"lazy\" width=\"2330\" height=\"1630\" style=\"width:100%;display:block;border-radius:10px 10px 0 0\">\n        </figure>\n        <p class=\"t-caption fig-cap\">Affinity mapping of the interview quotes</p>\n\n        <div class=\"pairs reveal\">\n          <div class=\"pair\">\n            <div><div class=\"k\">Barrier · Commitment debt</div><div class=\"t-h3\">Starting felt too big</div><p class=\"q\">\"A whole module feels like a lot after a shift.\"</p></div>\n            <div class=\"arr\">→</div>\n            <div><div class=\"k sol\">Solution</div><div class=\"t-h3\">Bite-sized checklist</div><p class=\"t-small\">Break modules into small tasks with time estimates.</p></div>\n          </div>\n          <div class=\"pair\">\n            <div><div class=\"k\">Barrier · No \"why today\"</div><div class=\"t-h3\">Nothing pulled them back</div><p class=\"q\">\"Nobody tells me if I'm behind until the review.\"</p></div>\n            <div class=\"arr\">→</div>\n            <div><div class=\"k sol\">Solution</div><div class=\"t-h3\">Personalized \"do this now\"</div><p class=\"t-small\">The agent picks the next step and says why it matters today.</p></div>\n          </div>\n          <div class=\"pair\">\n            <div><div class=\"k\">Barrier · Support gap</div><div class=\"t-h3\">No quick help</div><p class=\"q\">\"When the sim breaks I just stop and say I'll do it tomorrow.\"</p></div>\n            <div class=\"arr\">→</div>\n            <div><div class=\"k sol\">Solution</div><div class=\"t-h3\">Context-aware handoff</div><p class=\"t-small\">Upload a recording, and AI drafts the message to the instructor.</p></div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"statement reveal\" aria-label=\"Core goals\">\n        <p>Make starting feel <em>bite-sized</em>. Make <em>\"why today\"</em> obvious. Provide a <em>quick help path</em>.</p>\n        <span class=\"t-caption\">Core goals</span>\n      </section>\n\n      <!-- 03 -->\n      <section class=\"sec\" id=\"strategy\">\n        <div class=\"eyebrow\"><span class=\"n\">03</span>Strategy</div>\n        <h2 class=\"t-h2\">Ship fast, prove more later</h2>\n        <p class=\"t-body\">I weighed three options on <b>user impact</b> and <b>development cost</b>. The AI agent clearly won on impact, but engineering was still finishing AI inside the VR sessions, and latency and token cost were real concerns.</p>\n\n        <div class=\"options reveal\">\n          <div class=\"tile opt\"><div class=\"top\"><span class=\"t-caption\">Option 1</span></div><div class=\"t-h3\">Human mentor</div>\n            <div class=\"meter\"><span>Impact</span><span class=\"track\"><i style=\"--w:70%\"></i></span><span>Feasibility</span><span class=\"track\"><i style=\"--w:25%\"></i></span></div>\n            <p class=\"t-small\">High trust, but doesn't scale with the customer base.</p></div>\n          <div class=\"tile opt pick\"><div class=\"top\"><span class=\"t-caption\">Option 2</span><span class=\"tag accent\">MVP</span></div><div class=\"t-h3\">Checklist card</div>\n            <div class=\"meter\"><span>Impact</span><span class=\"track\"><i style=\"--w:55%\"></i></span><span>Feasibility</span><span class=\"track\"><i style=\"--w:90%\"></i></span></div>\n            <p class=\"t-small\">Low dev cost, ships now, builds on what exists.</p></div>\n          <div class=\"tile opt\"><div class=\"top\"><span class=\"t-caption\">Option 3</span></div><div class=\"t-h3\">Full AI agent</div>\n            <div class=\"meter\"><span>Impact</span><span class=\"track\"><i style=\"--w:95%\"></i></span><span>Feasibility</span><span class=\"track\"><i style=\"--w:30%\"></i></span></div>\n            <p class=\"t-small\">Best experience, blocked by latency and cost today.</p></div>\n        </div>\n\n        <ol class=\"roadmap reveal\">\n          <li class=\"hot\"><span class=\"dot\">1</span><div class=\"t-label\">Ship the checklist MVP</div><div class=\"t-caption\">Now · low cost, unblocks trainees</div></li>\n          <li><span class=\"dot\">2</span><div class=\"t-label\">Test the AI agent with WoZ</div><div class=\"t-caption\">Next · 24 trainees, no model needed</div></li>\n          <li class=\"if\"><span class=\"dot\">3</span><div class=\"t-label\">Build the agent, if proven</div><div class=\"t-caption\">Decision · only if the numbers hold</div></li>\n        </ol>\n\n        <figure class=\"breakout panel shot reveal\" aria-label=\"Checklist MVP screen\">\n          <img src=\"/TAPimgs/MVP_Checklist.png\" alt=\"Phase 1 checklist card pinned to the top of the TAP3D training page, breaking a module into small tasks with a progress bar\" loading=\"lazy\" width=\"2560\" height=\"1810\" style=\"width:100%;display:block;border-radius:10px 10px 0 0\">\n        </figure>\n        <p class=\"t-caption fig-cap\">Phase 1 · a checklist card pinned to the top of the training page</p>\n      </section>\n\n      <!-- 04 DESIGN -->\n      <section class=\"sec\" id=\"design\">\n        <div class=\"eyebrow\"><span class=\"n\">04</span>Design</div>\n        <h2 class=\"t-h2\">Designing the agent</h2>\n        <p class=\"t-body\">Before testing anything, I defined what the agent listens to, when it's allowed to speak, and where a human takes over. This blueprint became the shared spec for engineering and the script I followed as the \"AI\" in the Wizard-of-Oz study.</p>\n\n        <figure class=\"breakout panel blueprint reveal\" aria-label=\"Agent blueprint\">\n          <div class=\"bp-head\">\n            <div><div class=\"t-label\">Agent blueprint</div><div class=\"t-caption\">Select a behavior to trace its path</div></div>\n            <div class=\"bp-filter\" role=\"group\" aria-label=\"Filter by behavior\">\n              <button aria-pressed=\"true\" data-b=\"all\">All</button>\n              <button aria-pressed=\"false\" data-b=\"nudge\">Do this now</button>\n              <button aria-pressed=\"false\" data-b=\"handoff\">Issue handoff</button>\n              <button aria-pressed=\"false\" data-b=\"summary\">Weekly summary</button>\n            </div>\n          </div>\n          <div class=\"bp-grid\">\n            <div class=\"bp-col\">\n              <div class=\"bp-cap\">Signals</div>\n              <div class=\"bp-node\" data-on=\"nudge summary\"><b>Checklist state</b><span>Done, open and new tasks</span></div>\n              <div class=\"bp-node\" data-on=\"nudge summary\"><b>Time since last session</b><span>Idle gap per trainee</span></div>\n              <div class=\"bp-node\" data-on=\"nudge handoff\"><b>Stall point</b><span>Module and step where progress stops</span></div>\n              <div class=\"bp-node\" data-on=\"handoff\"><b>Learner recording</b><span>Uploaded by the trainee, on request</span></div>\n            </div>\n            <div class=\"bp-arrow\" aria-hidden=\"true\">→</div>\n            <div class=\"bp-col\">\n              <div class=\"bp-cap\">Agent rules</div>\n              <div class=\"bp-core\">\n                <div class=\"bp-rule\" data-on=\"nudge summary\"><span class=\"k\">Listen</span><p>Read progress, not content. No camera or audio unless the trainee uploads it.</p></div>\n                <div class=\"bp-rule\" data-on=\"nudge\"><span class=\"k\">Speak</span><p>Only between tasks. One next step, its time cost, and why it matters today.</p></div>\n                <div class=\"bp-rule\" data-on=\"handoff\"><span class=\"k\">Hand off</span><p>When a trainee is stuck, draft the message. The instructor decides what to send.</p></div>\n                <div class=\"bp-rule\" data-on=\"summary\"><span class=\"k\">Recap</span><p>Once a week, progress plus one suggested step.</p></div>\n              </div>\n            </div>\n            <div class=\"bp-arrow\" aria-hidden=\"true\">→</div>\n            <div class=\"bp-col\">\n              <div class=\"bp-cap\">Behaviors</div>\n              <div class=\"bp-node beh\" data-on=\"nudge\"><b>\"Do this now\"</b><span>Single next task with time estimate</span></div>\n              <div class=\"bp-node beh\" data-on=\"handoff\"><b>Issue handoff</b><span>AI-drafted context for the instructor</span></div>\n              <div class=\"bp-node beh\" data-on=\"summary\"><b>Weekly summary</b><span>Progress recap and next step</span></div>\n            </div>\n            <div class=\"bp-arrow\" aria-hidden=\"true\">→</div>\n            <div class=\"bp-col\">\n              <div class=\"bp-cap\">Surfaces</div>\n              <div class=\"bp-node\" data-on=\"nudge summary\"><b>Web &amp; tablet</b><span>Card at the top of the training page</span></div>\n              <div class=\"bp-node\" data-on=\"nudge\"><b>XR headset</b><span>Glanceable prompt between sessions</span></div>\n              <div class=\"bp-node human\" data-on=\"handoff\"><b>Instructor</b><span>Human in the loop</span></div>\n            </div>\n          </div>\n        </figure>\n        <p class=\"t-caption fig-cap\">One component, three behaviors, three surfaces, and a human for anything the agent can't solve</p>\n\n        <div class=\"decisions\">\n          <div class=\"dec reveal\">\n            <div class=\"dec-text\"><span class=\"t-caption\">Decision 01</span><div class=\"t-h3\">One next step, not a list</div><p class=\"t-small\">Trainees already had a list and ignored it. The agent always proposes exactly one task, with its time cost, so starting feels small.</p></div>\n            <div class=\"dec-vis tile\"><div class=\"mini-list\">\n              <span class=\"ml dim\">CNC Programming</span><span class=\"ml dim\">Equipment Lockout quiz</span><span class=\"ml dim\">Fluid Dynamics intro</span>\n              <span class=\"ml pick\"><i></i>Leak Checking · 10 min</span>\n            </div></div>\n          </div>\n          <div class=\"dec reveal\">\n            <div class=\"dec-text\"><span class=\"t-caption\">Decision 02</span><div class=\"t-h3\">Hand off to a human, don't fake an answer</div><p class=\"t-small\">Equipment errors in a simulation are high stakes. The agent packages the context, and the instructor stays the one who answers.</p></div>\n            <div class=\"dec-vis tile\"><div class=\"flow3\">\n              <span class=\"f\">Trainee<small>uploads clip</small></span><span class=\"fa\">→</span><span class=\"f ai\">AI<small>drafts context</small></span><span class=\"fa\">→</span><span class=\"f\">Instructor<small>replies</small></span>\n            </div></div>\n          </div>\n          <div class=\"dec reveal\">\n            <div class=\"dec-text\"><span class=\"t-caption\">Decision 03</span><div class=\"t-h3\">One widget, three surfaces</div><p class=\"t-small\">I designed the agent as a single modular component so it reads the same in a headset, on a laptop and on a tablet, and joined the design system instead of living on one screen.</p></div>\n            <div class=\"dec-vis tile\"><div class=\"devices\">\n              <div class=\"dv xr\"><span class=\"dv-l\">XR</span><div class=\"w\"><span class=\"bot\"></span>Leak Checking · 10 min</div></div>\n              <div class=\"dv web\"><span class=\"dv-l\">Web</span><div class=\"w\"><span class=\"bot\"></span><div><b>Next step</b><small>Leak Checking · 10 min</small></div></div></div>\n              <div class=\"dv tab\"><span class=\"dv-l\">Tablet</span><div class=\"w\"><span class=\"bot\"></span><div><b>Next up</b><small>10 min</small></div></div></div>\n            </div></div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 05 -->\n      <section class=\"sec\" id=\"validation\">\n        <div class=\"eyebrow\"><span class=\"n\">05</span>Validation</div>\n        <h2 class=\"t-h2\">Simulating AI to prove ROI</h2>\n        <p class=\"t-body\">The checklist made tasks visible, but it still waited for trainees to act. Three questions stayed unanswered.</p>\n\n        <div class=\"compare reveal\">\n          <div class=\"tile\"><div class=\"head\"><span class=\"t-label\">MVP · Checklist</span><span class=\"tag\">Phase 1</span></div>\n            <ul><li>See task list<span class=\"s yes\">solved</span></li><li>\"What should I do first?\"<span class=\"s no\">unsolved</span></li><li>\"I'm stuck, need help now\"<span class=\"s no\">unsolved</span></li><li>\"What did I do last week?\"<span class=\"s no\">unsolved</span></li></ul></div>\n          <div class=\"tile ai\"><div class=\"head\"><span class=\"t-label\">Proposed · AI layer</span><span class=\"tag accent\">Phase 2</span></div>\n            <ul><li>See task list<span class=\"s yes\">✓</span></li><li>Personalized \"do this now\"<span class=\"s yes\">✓</span></li><li>Context-aware issue handoff<span class=\"s yes\">✓</span></li><li>Weekly progress summary<span class=\"s yes\">✓</span></li></ul></div>\n        </div>\n\n        <p class=\"t-body\" style=\"margin-top:32px\">To convince skeptical stakeholders, I ran a <b>Wizard-of-Oz simulation with 24 trainees</b> and acted as the AI backend in real time.</p>\n\n        <figure class=\"breakout panel curtain reveal\" aria-label=\"Behind the curtain: what trainees saw and the console I used\">\n          <div class=\"cur-side art\">\n            <div class=\"cur-label\"><span class=\"tag\">What trainees saw</span></div>\n            <svg class=\"ill art-ill\" viewBox=\"0 0 520 400\" preserveAspectRatio=\"xMidYMid slice\" role=\"img\" aria-label=\"Illustration of a trainee in an XR headset inside a grid room, facing a floating agent prompt wired to the floor\">\n              <path class=\"art-grid\" d=\"M247 82V254 M288 82V254 M329 82V254 M370 82V254 M411 82V254 M206 125H452 M206 168H452 M206 211H452 M247 254L88 512 M288 254L252 512 M329 254L416 512 M370 254L580 512 M411 254L744 512 M206 125L-76 -4 M452 125L908 -4 M206 168L-76 168 M452 168L908 168 M206 211L-76 340 M452 211L908 340 M182 276H490 M150 306H543 M98 353H627 M18 426H756\"/>\n              <path class=\"art-edge\" d=\"M206 82L-76 -176 M452 82L908 -176 M206 254L-76 512 M452 254L908 512 M206 82H452V254H206Z\"/>\n              <path class=\"art-wire\" d=\"M400 196 V300 H560\"/>\n              <g>\n                <rect x=\"370\" y=\"88\" width=\"74\" height=\"48\" rx=\"6\" class=\"art-panel soft\"/>\n                <rect x=\"381\" y=\"100\" width=\"38\" height=\"4\" rx=\"2\" fill=\"#fff\" opacity=\".8\"/>\n                <rect x=\"381\" y=\"110\" width=\"50\" height=\"4\" rx=\"2\" fill=\"#fff\" opacity=\".5\"/>\n                <rect x=\"381\" y=\"120\" width=\"28\" height=\"4\" rx=\"2\" fill=\"#fff\" opacity=\".5\"/>\n              </g>\n              <image href=\"/TAPimgs/tap3d-trainee.png\" x=\"88\" y=\"118\" width=\"229\" height=\"300\" preserveAspectRatio=\"xMinYMin meet\"/>\n              <path class=\"ill-gaze g2 art-gaze\" d=\"M220 150 L262 160\"/>\n              <ellipse cx=\"300\" cy=\"206\" rx=\"34\" ry=\"6\" fill=\"#2f6fe4\" opacity=\".18\"/>\n              <g class=\"xr-prompt\" id=\"xrPrompt\">\n                <rect x=\"262\" y=\"144\" width=\"170\" height=\"52\" rx=\"10\" class=\"art-panel\"/>\n                <circle cx=\"282\" cy=\"170\" r=\"8\" class=\"art-bot\"/>\n                <circle cx=\"279\" cy=\"170\" r=\"1.5\" fill=\"#fff\"/><circle cx=\"285\" cy=\"170\" r=\"1.5\" fill=\"#fff\"/>\n                <text x=\"296\" y=\"166\" class=\"art-t1\" id=\"xrL1\">One step from your credit</text>\n                <text x=\"296\" y=\"181\" class=\"art-t2\" id=\"xrL2\">Leak Checking · 10 min</text>\n              </g>\n</svg>\n          </div>\n\n          <div class=\"cur-divider\" aria-hidden=\"true\"><span>Curtain</span></div>\n\n          <div class=\"cur-side\">\n            <div class=\"cur-label\"><span class=\"tag accent\">What I operated</span></div>\n            <div class=\"app console\">\n              <div class=\"app-nav\"><b class=\"on\">Wizard console</b><span>Trainee 07</span><span class=\"sp live\">● Live</span></div>\n              <div class=\"app-body\">\n                <div class=\"sig\"><span>Module 3 · Step 4</span><span>Idle 2 days</span><span>1 task to credit</span></div>\n                <div class=\"tpls\" role=\"radiogroup\" aria-label=\"Response templates\">\n                  <button role=\"radio\" aria-checked=\"true\" data-msg=\"nudge\"><span class=\"tk\">Nudge</span>One step from your <i>credit</i>. <i>Leak Checking</i> takes about <i>10</i> min.</button>\n                  <button role=\"radio\" aria-checked=\"false\" data-msg=\"handoff\"><span class=\"tk\">Handoff</span>Draft to <i>instructor</i>: stuck at <i>step 4</i>, clip <i>0:31</i>.</button>\n                  <button role=\"radio\" aria-checked=\"false\" data-msg=\"recap\"><span class=\"tk\">Recap</span>This week <i>3/5</i> modules. Next: <i>Lockout quiz</i>.</button>\n                </div>\n                <button class=\"up\" id=\"sendXR\">Send to headset</button>\n              </div>\n            </div>\n          </div>\n        </figure>\n        <p class=\"t-caption fig-cap\">Trainees saw an agent. Behind the curtain, I answered with templates and live signals, following the blueprint's rules.</p>\n\n        <div class=\"breakout panel demo reveal\" id=\"demo\">\n          <div class=\"demo-tabs\" role=\"tablist\">\n            <button role=\"tab\" aria-selected=\"true\" data-tab=\"0\"><span>01</span>Issue handoff</button>\n            <button role=\"tab\" aria-selected=\"false\" data-tab=\"1\"><span>02</span>\"Do this now\"</button>\n            <button role=\"tab\" aria-selected=\"false\" data-tab=\"2\"><span>03</span>Weekly summary</button>\n          </div>\n          <div class=\"demo-grid\">\n            <div class=\"demo-copy\" id=\"demoCopy\"></div>\n            <div class=\"stage\" id=\"stage\"></div>\n          </div>\n        </div>\n\n        <div class=\"deltas reveal\">\n          <div><div class=\"t-caption\">Issue resolution</div><div class=\"delta\"><s>33%</s><span class=\"arr\">→</span><b>71%</b></div><div class=\"t-small\">+38pt with context-aware handoff</div></div>\n          <div><div class=\"t-caption\">Task start rate</div><div class=\"delta\"><s>38%</s><span class=\"arr\">→</span><b>63%</b></div><div class=\"t-small\">+25pt with \"do this now\" nudges</div></div>\n        </div>\n        <p class=\"t-caption method\">How we measured · 24 trainees · checklist MVP vs. simulated agent behaviors. A human played the AI, so these numbers show demand for the behavior, not model accuracy.</p>\n      </section>\n\n      <!-- 05 -->\n      <section class=\"sec\" id=\"outcome\">\n        <div class=\"eyebrow\"><span class=\"n\">06</span>Outcome</div>\n        <h2 class=\"t-h2\">The CFO said yes</h2>\n        <p class=\"t-body\">I put the AI agent screens next to the MVP screens for engineering, the PM and the CFO. The CFO was worried about <b>ROI and development cost</b>, and the simulation numbers answered it. We rolled the agent out right after the VR AI integration wrapped.</p>\n\n        <figure class=\"breakout panel duo reveal\" aria-label=\"MVP and AI agent screens side by side\">\n          <div class=\"duo-col\">\n            <div class=\"duo-label\"><span class=\"tag\">Before</span><span class=\"t-caption\">Checklist MVP</span></div>\n            <img src=\"/TAPimgs/MVP_Checklist.png\" alt=\"Before: the checklist MVP, a static task list that waits for the trainee to decide what to do next\" loading=\"lazy\" width=\"2560\" height=\"1810\" style=\"width:100%;display:block;border-radius:10px 10px 0 0;box-shadow:var(--shot-shadow)\">\n          </div>\n          <div class=\"duo-col\">\n            <div class=\"duo-label\"><span class=\"tag accent\">After</span><span class=\"t-caption\">AI agent</span></div>\n            <img src=\"/TAPimgs/TAP3D_Final_Product.png\" alt=\"After: the shipped AI agent proactively suggesting the next step and why it matters, with a weekly progress recap, inside the training UI\" loading=\"lazy\" width=\"2639\" height=\"1810\" style=\"width:100%;display:block;border-radius:10px 10px 0 0;box-shadow:var(--shot-shadow)\">\n          </div>\n        </figure>\n        <p class=\"t-caption fig-cap\">The comparison I brought to engineering, the PM and the CFO</p>\n\n        <div class=\"list reveal\">\n          <div><span class=\"n\">01</span><div><div class=\"t-h3\">Live across the training flow</div><p class=\"t-small\">Built as a modular AI widget inside the design system, so it looks and behaves the same everywhere.</p></div></div>\n          <div><span class=\"n\">02</span><div><div class=\"t-h3\">Expanding globally</div><p class=\"t-small\">I pitched that consistent AI guidance produces job-ready talent faster. Chinese localization is in progress.</p></div></div>\n        </div>\n        <p class=\"t-caption\" style=\"margin-top:16px\">Post-rollout completion metrics fall outside my engagement window. The validation data above is what secured the investment.</p>\n      </section>\n\n      <!-- 06 -->\n      <section class=\"sec\" id=\"reflection\" style=\"border-bottom:0\">\n        <div class=\"eyebrow\"><span class=\"n\">07</span>Reflection</div>\n        <h2 class=\"t-h2\">What I'd carry forward</h2>\n        <div class=\"insight reveal\" style=\"margin-top:8px\"><p>Pre-launch simulation testing wasn't common at TAP3D. <em>This project made it part of how the team decides what to build.</em></p></div>\n        <figure class=\"breakout panel shot reveal\" aria-label=\"Presenting the Wizard-of-Oz results to the C-suite\">\n          <img src=\"/TAPimgs/TAP3D_Zoom.png\" alt=\"Presenting the Wizard-of-Oz study results to the C-suite over a video call\" loading=\"lazy\" width=\"2014\" height=\"999\" style=\"width:100%;display:block;border-radius:10px 10px 0 0\">\n        </figure>\n        <p class=\"t-caption fig-cap\">Pitching the WoZ results to the C-suite</p>\n        <div class=\"list reveal\">\n          <div><span class=\"n\">01</span><div><div class=\"t-h3\">Simulate before you build</div><p class=\"t-small\">Wizard-of-Oz turned an opinion into numbers a CFO could sign off on, before any model cost was spent.</p></div></div>\n          <div><span class=\"n\">02</span><div><div class=\"t-h3\">Design the component, not the screen</div><p class=\"t-small\">A modular widget let the agent ship across VR, web and tablet without redesigning each surface.</p></div></div>\n          <div><span class=\"n\">03</span><div><div class=\"t-h3\">Trade-offs are a design material</div><p class=\"t-small\">Phasing the work kept engineering unblocked and still got to the ambitious version.</p></div></div>\n        </div>\n      </section>\n    </div>\n  </div>\n\n  <a class=\"next\" id=\"next\" href=\"#\">\n    <div class=\"row\">\n      <div><div class=\"t-caption\" style=\"margin-bottom:8px\">Next project · LePal</div><div class=\"t-h2\">Breaking the 72-hour drop-off in AI journaling</div></div>\n      <span class=\"arrow\" aria-hidden=\"true\">→</span>\n    </div>\n    <div class=\"panel\"><div class=\"bubble\">How was today? I noticed you wrote less this week. Want to start small?</div></div>\n  </a>\n</main>\n\n<div class=\"sum\" id=\"sum\" hidden role=\"dialog\" aria-modal=\"true\" aria-label=\"Summary mode\">\n  <div class=\"sum-card\">\n    <div class=\"sum-top\">\n      <div class=\"sum-dots\" id=\"sumDots\"><i class=\"on\"></i><i></i><i></i><i></i><i></i></div>\n      <span class=\"t-caption sum-role\">TAP3D · Lead Product Designer · 6 months</span>\n      <button class=\"icon-btn\" id=\"sumClose\" aria-label=\"Close summary\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n    </div>\n\n    <div class=\"slide on\">\n      <div class=\"s-l\"><span class=\"t-caption\">01 · Problem</span>\n        <p class=\"big\">Trainees stalled at <em>Module 3</em>, and the data couldn't say why.</p>\n        <p class=\"t-small\">TAP3D trains technicians for advanced manufacturing across VR, web and tablet. Trainees weren't reaching the review stage, so customers saw slow job-readiness and retention suffered.</p></div>\n      <div class=\"s-r\"><div class=\"mini-bars\">\n        <div><i style=\"--h:92%\"></i><span>M1</span></div><div><i style=\"--h:74%\"></i><span>M2</span></div><div class=\"hot\"><i style=\"--h:41%\"></i><span>M3</span></div><div><i style=\"--h:28%\"></i><span>M4</span></div><div><i style=\"--h:19%\"></i><span>M5</span></div><div><i style=\"--h:12%\"></i><span>Review</span></div>\n      </div><p class=\"t-caption\">Completion by module · illustrative · <b style=\"color:var(--accent)\">−33pt</b> from M2 to M3</p></div>\n    </div>\n\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">02 · Research</span>\n        <p class=\"big\">9 interviews surfaced <em>3 barriers</em> the logs couldn't show.</p>\n        <p class=\"t-small\">I led 9 in-depth interviews and coded 200+ quotes into an affinity map. Each barrier became a design requirement.</p></div>\n      <div class=\"s-r s-rows\">\n        <div><span class=\"t-caption\">Commitment debt</span><p class=\"t-label\">\"A whole module feels like a lot after a shift.\"</p><span class=\"to\">→ Bite-sized checklist</span></div>\n        <div><span class=\"t-caption\">No \"why today\"</span><p class=\"t-label\">\"Nobody tells me if I'm behind until the review.\"</p><span class=\"to\">→ Personalized \"do this now\"</span></div>\n        <div><span class=\"t-caption\">Support gap</span><p class=\"t-label\">\"When the sim breaks I just stop.\"</p><span class=\"to\">→ Context-aware handoff to instructor</span></div>\n      </div>\n    </div>\n\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">03 · Strategy</span>\n        <p class=\"big\">Ship the cheap fix now. <em>Prove the agent</em> before building it.</p>\n        <p class=\"t-small\">The AI agent won on impact, but engineering was still finishing AI inside VR, and latency and token cost were open risks. I split the work so trainees got help immediately and the bigger bet had to earn its budget.</p></div>\n      <div class=\"s-r s-rows\">\n        <div><span class=\"t-caption\">Phase 1 · Now</span><p class=\"t-label\">Checklist card pinned to the training page</p><span class=\"to\">Low cost, ships with existing components</span></div>\n        <div><span class=\"t-caption\">Phase 2 · Next</span><p class=\"t-label\">Wizard-of-Oz test of the AI agent</p><span class=\"to\">24 trainees, I acted as the AI in real time</span></div>\n        <div><span class=\"t-caption\">Phase 3 · Only if proven</span><p class=\"t-label\">Build the agent for real</p><span class=\"to\">Decision gate: numbers go to the CFO</span></div>\n      </div>\n    </div>\n\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">04 · Validation</span>\n        <p class=\"big\">Simulated AI moved the two numbers that mattered.</p>\n        <p class=\"t-small\">I tested three agent behaviors: a context-aware issue handoff, a personalized \"do this now\" nudge and a weekly summary. Trainees used them as if a real model were running.</p></div>\n      <div class=\"s-r s-deltas\">\n        <div><span class=\"t-caption\">Issue resolution</span><div class=\"delta\"><s>33%</s><span class=\"arr\">→</span><b>71%</b></div></div>\n        <div><span class=\"t-caption\">Task start rate</span><div class=\"delta\"><s>38%</s><span class=\"arr\">→</span><b>63%</b></div></div>\n        <p class=\"t-caption\">Wizard-of-Oz · n=24 · before vs. with agent behaviors</p>\n      </div>\n    </div>\n\n    <div class=\"slide\">\n      <div class=\"s-l\"><span class=\"t-caption\">05 · Outcome</span>\n        <p class=\"big\">The CFO approved the rollout. <em>The agent is live.</em></p>\n        <p class=\"t-small\">The simulation answered the ROI question before any model cost was spent. The agent shipped as a modular component in the design system, and Chinese localization is underway.</p></div>\n      <div class=\"s-r s-rows\">\n        <div><span class=\"t-caption\">What I owned</span><p class=\"t-label\">Research, AI behavior design, WoZ study, C-suite pitch</p></div>\n        <div><span class=\"t-caption\">What shipped</span><p class=\"t-label\">AI agent across the training flow, as one reusable widget</p></div>\n        <div><span class=\"t-caption\">What I'd repeat</span><p class=\"t-label\">Simulate before you build. It turned a debate into a decision.</p></div>\n      </div>\n    </div>\n\n    <div class=\"sum-nav\"><span class=\"t-caption\" id=\"sumCount\">1 / 5</span><button class=\"icon-btn glass\" id=\"sumPrev\" aria-label=\"Previous slide\">←</button><button class=\"icon-btn glass\" id=\"sumNext\" aria-label=\"Next slide\">→</button></div>\n  </div>\n</div>";
export const js = "\n(function(){\n  var root=document.documentElement;\n  var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  /* theme toggle (follows system until clicked) */\n  document.getElementById('themeBtn').addEventListener('click',function(){\n    var cur=root.getAttribute('data-theme')||'dark';\n    root.setAttribute('data-theme',cur==='dark'?'light':'dark');\n  });\n\n  /* TOC active + hide while a breakout moment is centered */\n  var links=[].slice.call(document.querySelectorAll('#toc a')), toc=document.getElementById('toc');\n  if('IntersectionObserver' in window){\n    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){links.forEach(function(a){a.classList.toggle('on',a.getAttribute('href')==='#'+e.target.id)})}})},{rootMargin:'-40% 0px -55% 0px'});\n    links.forEach(function(a){var s=document.querySelector(a.getAttribute('href'));s&&io.observe(s)});\n\n  }\n\n  /* reveal: visible at rest; only items below the fold are primed, then animate in */\n  function countUp(n){var to=+n.dataset.to,suf=n.dataset.suffix||'',t0=null;n.textContent='0';\n    function step(t){t0=t0||t;var p=Math.min((t-t0)/1100,1);p=1-Math.pow(1-p,3);n.textContent=Math.round(to*p)+(p===1?suf:'');if(p<1)requestAnimationFrame(step)}requestAnimationFrame(step)}\n  if(!reduce&&'IntersectionObserver' in window){\n    var vh=innerHeight;\n    var ro=new IntersectionObserver(function(es){es.forEach(function(e){\n      if(!e.isIntersecting)return; var el=e.target; ro.unobserve(el);\n      requestAnimationFrame(function(){el.classList.remove('pre-r','pre');\n        [].forEach.call(el.querySelectorAll('[data-to]'),countUp);});\n    })},{threshold:.2});\n    [].forEach.call(document.querySelectorAll('.reveal'),function(el){\n      if(el.getBoundingClientRect().top>vh*0.9){el.classList.add('pre-r');if(el.hasAttribute('data-grow'))el.classList.add('pre');ro.observe(el)}\n    });\n    var cover=document.getElementById('cover');requestAnimationFrame(function(){cover.classList.add('in')});\n  } else { document.getElementById('cover').classList.add('in') }\n\n  /* hero motion: use the landing thumbnail animation on the real site */\n  (function(){\n    var host=location.hostname, slot=document.getElementById('heroMedia');\n    var onSite=/(^|\\.)jihokim\\.me$/.test(host)||host==='localhost'||host==='127.0.0.1';\n    if(!slot||!onSite||reduce) return;\n    var f=document.createElement('iframe'); f.src=slot.dataset.src; f.title='TAP3D product motion'; f.tabIndex=-1; f.loading='eager';\n    f.addEventListener('load',function(){f.classList.add('ready')}); slot.appendChild(f);\n  })();\n\n  /* blueprint filter */\n  var bp=document.querySelector('.blueprint'), bpBtns=[].slice.call(document.querySelectorAll('.bp-filter button'));\n  bpBtns.forEach(function(btn){btn.addEventListener('click',function(){\n    var b=btn.dataset.b; bpBtns.forEach(function(x){x.setAttribute('aria-pressed',x===btn?'true':'false')});\n    bp.classList.toggle('filtering',b!=='all');\n    [].forEach.call(bp.querySelectorAll('[data-on]'),function(n){n.classList.toggle('lit',b!=='all'&&n.dataset.on.split(' ').indexOf(b)>-1)});\n  })});\n\n  /* behind the curtain */\n  var msgs={nudge:['One step from your credit','Leak Checking · 10 min'],handoff:['Sent to your instructor','They\\'ll reply in this session'],recap:['This week: 3 of 5 modules','Next: Lockout quiz · 8 min']};\n  var tpl=[].slice.call(document.querySelectorAll('.tpls button')), sel='nudge', pr=document.getElementById('xrPrompt'), gz=document.querySelector('.ill-gaze.g2');\n  tpl.forEach(function(b){b.addEventListener('click',function(){sel=b.dataset.msg;tpl.forEach(function(x){x.setAttribute('aria-checked',x===b?'true':'false')})})});\n  document.getElementById('sendXR').addEventListener('click',function(){\n    pr.classList.add('out');\n    setTimeout(function(){document.getElementById('xrL1').textContent=msgs[sel][0];document.getElementById('xrL2').textContent=msgs[sel][1];\n      pr.classList.remove('out');gz.classList.remove('pulse');void gz.getBoundingClientRect();gz.classList.add('pulse')},reduce?0:350);\n  });\n\n  /* WoZ demo */\n  var tabs=[].slice.call(document.querySelectorAll('[data-tab]')), copy=document.getElementById('demoCopy'), stage=document.getElementById('stage'), timers=[];\n  function clear(){timers.forEach(clearTimeout);timers=[]}\n  function typeInto(el,text,speed,done){var i=0;(function tick(){el.textContent=text.slice(0,++i);if(i<text.length)timers.push(setTimeout(tick,reduce?0:speed));else done&&done()})()}\n  var scenes=[\n    {h:'Issue handoff',p:'A trainee stuck on Module 3 uploads a short screen or VR recording. The agent drafts a message with context, so a \"rage quit\" becomes a quick escalation.',hint:'Click \"Upload to AI\" to run it',\n     render:function(){\n      stage.innerHTML='<div class=\"rec\"><span class=\"dot\"></span><div><b>Learner stuck on Module 3</b><small>Recording · 0:42</small></div></div>'+\n        '<div class=\"file\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"#7a869a\" stroke-width=\"1.4\"><rect x=\"2\" y=\"3.5\" width=\"12\" height=\"9\" rx=\"1.5\"/><path d=\"M7 6.5v3l2.5-1.5z\" fill=\"#7a869a\"/></svg><div style=\"flex:1\"><div class=\"bar\"><i id=\"upBar\"></i></div><small>screen-recording-module3.webm</small></div></div>'+\n        '<button class=\"up\" id=\"upBtn\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M8 11V3M4.5 6.5L8 3l3.5 3.5M3 13h10\"/></svg>Upload to AI</button>';\n      document.getElementById('upBtn').addEventListener('click',function(){\n        var btn=this;btn.disabled=true;btn.textContent='Analyzing recording…';document.getElementById('upBar').style.width='100%';\n        timers.push(setTimeout(function(){\n          btn.remove();\n          var d=document.createElement('div');d.className='draft';\n          d.innerHTML='<div class=\"who\"><span class=\"bot\"></span>AI draft to instructor</div><div class=\"typed\"></div><div class=\"meta2\"><span>Module 3 · Step 4</span><span>Clip 0:31–0:42</span><span>Tool: end mill</span></div>';\n          stage.appendChild(d);\n          typeInto(d.querySelector('.typed'),'Hi Alex, Jiho is stuck at step 4 of Mill Cutting Tools. The end mill keeps snapping back after selection (clip 0:31). Could you check the tool path settings? They want to finish today.',14,function(){d.classList.add('done');\n            var r=document.createElement('button');r.className='reset';r.textContent='Replay';r.onclick=function(){show(0)};stage.appendChild(r)});\n        },reduce?0:1100));\n      });\n    }},\n    {h:'\"Do this now\"',p:'Instead of a list that waits, the agent picks one next step, sizes it in minutes and says why it matters today.',hint:'Plays automatically',\n     render:function(){\n      stage.innerHTML='<div class=\"card\"><h5>Today\\'s Checklist</h5><div class=\"sub\">2 out of 4 tasks completed · Keep going!</div><div class=\"prog\"><i style=\"--w:50%\"></i></div><div class=\"task\"><span class=\"c done\"></span>Simulation: Mill Cutting Tools</div><div class=\"task\"><span class=\"c\"></span>CNC Programming</div><div class=\"task\"><span class=\"c\"></span>Leak Checking</div></div>';\n      timers.push(setTimeout(function(){\n        var m=document.createElement('div');m.className='agent-msg';m.style.opacity='0';m.style.transform='translateY(8px)';m.style.transition='all .5s';\n        m.innerHTML='<span class=\"bot\"></span><div><p class=\"typed\"></p><span class=\"cta\">Start Leak Checking · 10 min</span></div>';\n        stage.insertBefore(m,stage.firstChild);requestAnimationFrame(function(){m.style.opacity='1';m.style.transform='none'});\n        typeInto(m.querySelector('.typed'),'You\\'re one task from your safety credit. Leak Checking takes about 10 minutes. Want to do it now?',16);\n      },reduce?0:500));\n    }},\n    {h:'Weekly summary',p:'Every week the agent recaps progress and proposes the next step, so trainees pick up where they left off after a break.',hint:'Plays automatically',\n     render:function(){\n      stage.innerHTML='<div class=\"card\"><h5><span class=\"bot\"></span>Your weekly summary</h5><div class=\"kpis\"><div><small>Modules completed</small><b id=\"k1\">0/5</b></div><div><small>Time invested</small><b id=\"k2\">0h</b></div><div><small>Safety score</small><b id=\"k3\">72%</b></div></div></div>'+\n        '<div class=\"agent-msg\"><span class=\"bot\"></span><div><p><b style=\"color:var(--ui-navy)\">Suggested next step</b><br>Finish the \"Equipment Lockout\" quiz (8 min) to complete your safety certification this week.</p></div></div>';\n      var k1=document.getElementById('k1'),k2=document.getElementById('k2'),k3=document.getElementById('k3');\n      [1,2,3].forEach(function(v,i){timers.push(setTimeout(function(){k1.textContent=v+'/5'},reduce?0:300+i*250))});\n      timers.push(setTimeout(function(){k2.textContent='2h 15m'},reduce?0:700));\n      [76,81,85,88].forEach(function(v,i){timers.push(setTimeout(function(){k3.textContent=v+'%'},reduce?0:400+i*180))});\n    }}\n  ];\n  function show(i){clear();tabs.forEach(function(t,j){t.setAttribute('aria-selected',j===i?'true':'false')});\n    var s=scenes[i];copy.innerHTML='<div class=\"t-h3\">'+s.h+'</div><p class=\"t-small\">'+s.p+'</p><span class=\"hint\">↳ '+s.hint+'</span>';s.render()}\n  tabs.forEach(function(t,i){t.addEventListener('click',function(){show(i)})});\n  show(0);\n\n  /* summary mode */\n  var sum=document.getElementById('sum'), slides=[].slice.call(sum.querySelectorAll('.slide')), dots=[].slice.call(sum.querySelectorAll('#sumDots i')), cur=0, lastFocus=null;\n  function go(i){cur=(i+slides.length)%slides.length;slides.forEach(function(s,j){s.classList.toggle('on',j===cur)});dots.forEach(function(d,j){d.classList.toggle('on',j<=cur)});document.getElementById('sumCount').textContent=(cur+1)+' / '+slides.length}\n  function open(){lastFocus=document.activeElement;sum.hidden=false;go(0);document.getElementById('sumNext').focus();document.body.style.overflow='hidden'}\n  function close(){sum.hidden=true;document.body.style.overflow='';lastFocus&&lastFocus.focus()}\n  [].forEach.call(document.querySelectorAll('[data-open-summary]'),function(b){b.addEventListener('click',open)});\n  document.getElementById('sumClose').addEventListener('click',close);\n  document.getElementById('sumNext').addEventListener('click',function(){go(cur+1)});\n  document.getElementById('sumPrev').addEventListener('click',function(){go(cur-1)});\n  sum.addEventListener('click',function(e){if(e.target===sum)close()});\n  document.addEventListener('keydown',function(e){if(sum.hidden)return;if(e.key==='Escape')close();if(e.key==='ArrowRight')go(cur+1);if(e.key==='ArrowLeft')go(cur-1)});\n})();\n";
